theme_pub2 <- function(base_size = 18) {
  theme_minimal(base_size = base_size) +
    theme(
      plot.background  = element_rect(fill = "white", color = NA),
      panel.background = element_rect(fill = "white", color = NA),
      panel.grid.major = element_line(color = pal_graybg, linewidth = 0.7),
      panel.grid.minor = element_blank(),
      axis.title = element_text(face = "bold", color = "black", size = base_size + 1),
      axis.text  = element_text(color = "black", size = base_size - 1),
      legend.title = element_text(face = "bold", size = base_size),
      legend.text  = element_text(size = base_size - 1),
      strip.background = element_rect(fill = pal_graybg, color = "grey70"),
      strip.text = element_text(face = "bold", size = base_size, color = "black"),
      plot.title = element_text(face = "bold", size = base_size + 4, color = "black", hjust = 0),
      plot.subtitle = element_text(size = base_size, color = "grey30", hjust = 0),
      plot.caption = element_text(size = base_size - 3, color = "grey40"),
      axis.line = element_line(color = "black", linewidth = 0.4),
      plot.margin = margin(12, 16, 12, 16)
    )
}

save_plot_dual2 <- function(plot_obj, filename_stub, width = 10, height = 7) {
  pdf_path <- file.path(dir_06_figures, paste0(filename_stub, ".pdf"))
  png_path <- file.path(dir_06_figures, paste0(filename_stub, ".png"))
  ggsave(filename = pdf_path, plot = plot_obj, width = width, height = height)
  ggsave(filename = png_path, plot = plot_obj, width = width, height = height, dpi = 600)
  cat("Saved figure:", pdf_path, "\n")
  cat("Saved figure:", png_path, "\n")
}

