sql_path <- function(path) {
  path <- gsub("\\\\", "/", path)
  paste0("'", gsub("'", "''", path), "'")
}

create_csv_view <- function(con, view_name, path) {
  sql <- sprintf(
    "
    CREATE OR REPLACE VIEW %s AS
    SELECT *
    FROM read_csv_auto(%s, header = true, sample_size = 100000);
    ",
    view_name,
    sql_path(path)
  )
  DBI::dbExecute(con, sql)
}

safe_fwrite <- function(x, path) {
  data.table::fwrite(x, path)
  cat("Saved:", path, "\n")
}

add_sheet <- function(wb, sheet_name, df) {
  sheet_name <- substr(sheet_name, 1, 31)
  openxlsx::addWorksheet(wb, sheet_name)
  openxlsx::writeDataTable(
    wb, sheet = sheet_name, x = df,
    tableStyle = "TableStyleMedium2", withFilter = TRUE
  )
  openxlsx::freezePane(wb, sheet = sheet_name, firstRow = TRUE)
  if (ncol(df) > 0) {
    openxlsx::setColWidths(wb, sheet = sheet_name, cols = 1:ncol(df), widths = "auto")
  }
}

parse_datetime_safe <- function(x) {
  x <- as.character(x)
  x <- trimws(x)
  x[x %in% c("", "NA", "NaN", "NULL", "null")] <- NA_character_

  out <- suppressWarnings(as.POSIXct(x, format = "%Y-%m-%d %H:%M:%S", tz = "UTC"))

  idx <- is.na(out) & !is.na(x)
  if (any(idx)) {
    out[idx] <- suppressWarnings(as.POSIXct(x[idx], format = "%Y-%m-%d %H:%M", tz = "UTC"))
  }

  idx <- is.na(out) & !is.na(x)
  if (any(idx)) {
    out[idx] <- suppressWarnings(as.POSIXct(x[idx], format = "%Y-%m-%d", tz = "UTC"))
  }

  out
}

parse_date_safe <- function(x) {
  x <- as.character(x)
  x <- trimws(x)
  x[x %in% c("", "NA", "NaN", "NULL", "null")] <- NA_character_

  out <- suppressWarnings(as.Date(x, format = "%Y-%m-%d"))

  idx <- is.na(out) & !is.na(x)
  if (any(idx)) {
    out[idx] <- suppressWarnings(as.Date(substr(x[idx], 1, 10), format = "%Y-%m-%d"))
  }

  out
}

## =========================================================
## 5. Read Step01 cohort and fix time columns
## =========================================================
cohort <- data.table::fread(input_cohort_csv)

## Convert datetime columns
for (cc in c("admittime", "dischtime", "deathtime", "intime", "outtime")) {
  if (cc %in% names(cohort)) {
    cohort[[cc]] <- parse_datetime_safe(cohort[[cc]])
  }
}

## Convert date of death
if ("dod" %in% names(cohort)) {
  cohort$dod <- parse_date_safe(cohort$dod)
} else {
  cohort$dod <- as.Date(NA)
}

## Create usable death timestamp:
## priority 1 = deathtime; priority 2 = dod at noon
cohort$dod_noon <- as.POSIXct(NA_real_, origin = "1970-01-01", tz = "UTC")
valid_dod <- !is.na(cohort$dod)
cohort$dod_noon[valid_dod] <- as.POSIXct(
  paste0(format(cohort$dod[valid_dod], "%Y-%m-%d"), " 12:00:00"),
  format = "%Y-%m-%d %H:%M:%S",
  tz = "UTC"
)

cohort$death_time_any <- cohort$deathtime
idx_need_dod <- is.na(cohort$death_time_any) & !is.na(cohort$dod_noon)
cohort$death_time_any[idx_need_dod] <- cohort$dod_noon[idx_need_dod]

cat("Step01 cohort loaded:", nrow(cohort), "rows\n")
cat("Non-missing deathtime:", sum(!is.na(cohort$deathtime)), "\n")
cat("Non-missing dod:", sum(!is.na(cohort$dod)), "\n")
cat("Non-missing death_time_any:", sum(!is.na(cohort$death_time_any)), "\n\n")

