DBI::dbExecute(con, "
CREATE OR REPLACE TABLE dx_all_clean AS
SELECT
  CAST(d.subject_id AS BIGINT) AS subject_id,
  CAST(d.hadm_id AS BIGINT) AS hadm_id,
  TRY_CAST(d.seq_num AS INTEGER) AS seq_num,
  CAST(d.icd_version AS INTEGER) AS icd_version,
  upper(replace(trim(CAST(d.icd_code AS VARCHAR)), '.', '')) AS icd_code_clean,
  CAST(dic.long_title AS VARCHAR) AS diagnosis_title
FROM diagnoses_icd d
LEFT JOIN d_icd_diagnoses dic
  ON upper(replace(trim(CAST(d.icd_code AS VARCHAR)), '.', ''))
     = upper(replace(trim(CAST(dic.icd_code AS VARCHAR)), '.', ''))
 AND CAST(d.icd_version AS INTEGER) = CAST(dic.icd_version AS INTEGER);
")

DBI::dbExecute(con, "
CREATE OR REPLACE TABLE prior_cad_flags AS
SELECT
  subject_id,
  hadm_id,
  MAX(CASE
    WHEN icd_version = 9 AND (
      icd_code_clean LIKE '412%' OR
      icd_code_clean LIKE '413%' OR
      icd_code_clean LIKE '414%'
    ) THEN 1
    WHEN icd_version = 10 AND (
      icd_code_clean LIKE 'I20%' OR
      icd_code_clean LIKE 'I25%'
    ) THEN 1
    ELSE 0
  END) AS prior_cad_or_chronic_ihd
FROM dx_all_clean
GROUP BY subject_id, hadm_id;
")

prior_cad_df <- DBI::dbGetQuery(con, "
SELECT
  c.subject_id,
  c.hadm_id,
  COALESCE(p.prior_cad_or_chronic_ihd, 0) AS prior_cad_or_chronic_ihd
FROM cohort_base_r c
LEFT JOIN prior_cad_flags p
  ON c.subject_id = p.subject_id
 AND c.hadm_id = p.hadm_id;
")

cohort <- cohort %>%
  left_join(prior_cad_df, by = c("subject_id", "hadm_id"))

if ("cad_or_ihd" %in% names(cohort)) {
  cohort <- cohort %>% rename(cad_or_ihd_original = cad_or_ihd)
}

prior_cad_summary <- cohort %>%
  count(prior_cad_or_chronic_ihd, name = "n") %>%
  mutate(pct = n / sum(n) * 100)

