## =========================================================
## 9. Extract 0-72h laboratory and vital records
## =========================================================
DBI::dbExecute(con, "
CREATE OR REPLACE TABLE lab_target_72h AS
SELECT
  c.subject_id,
  c.hadm_id,
  c.stay_id,
  CAST(c.intime AS TIMESTAMP) AS intime,
  m.domain,
  m.variable,
  m.scientific_module,
  m.itemid,
  CAST(l.charttime AS TIMESTAMP) AS charttime,
  date_diff('minute', CAST(c.intime AS TIMESTAMP), CAST(l.charttime AS TIMESTAMP)) / 60.0 AS hours_from_icu,
  TRY_CAST(l.valuenum AS DOUBLE) AS valuenum
FROM cohort_enhanced_r c
INNER JOIN labevents l
  ON c.subject_id = CAST(l.subject_id AS BIGINT)
 AND c.hadm_id = CAST(l.hadm_id AS BIGINT)
INNER JOIN lab_item_map m
  ON CAST(l.itemid AS BIGINT) = m.itemid
WHERE
  TRY_CAST(l.valuenum AS DOUBLE) IS NOT NULL
  AND CAST(l.charttime AS TIMESTAMP) >= CAST(c.intime AS TIMESTAMP)
  AND CAST(l.charttime AS TIMESTAMP) < CAST(c.intime AS TIMESTAMP) + INTERVAL '72 hours';
")

DBI::dbExecute(con, "
CREATE OR REPLACE TABLE lab_target_72h_clean AS
SELECT
  *,
  CASE
    WHEN variable = 'wbc' THEN CASE WHEN valuenum < 4 OR valuenum > 12 THEN 1 ELSE 0 END
    WHEN variable = 'hemoglobin' THEN CASE WHEN valuenum < 10 THEN 1 ELSE 0 END
    WHEN variable = 'hematocrit' THEN CASE WHEN valuenum < 30 THEN 1 ELSE 0 END
    WHEN variable = 'platelet' THEN CASE WHEN valuenum < 150 THEN 1 ELSE 0 END
    WHEN variable = 'creatinine' THEN CASE WHEN valuenum > 1.5 THEN 1 ELSE 0 END
    WHEN variable = 'bun' THEN CASE WHEN valuenum > 25 THEN 1 ELSE 0 END
    WHEN variable = 'sodium' THEN CASE WHEN valuenum < 135 OR valuenum > 145 THEN 1 ELSE 0 END
    WHEN variable = 'potassium' THEN CASE WHEN valuenum < 3.5 OR valuenum > 5.0 THEN 1 ELSE 0 END
    WHEN variable = 'chloride' THEN CASE WHEN valuenum < 98 OR valuenum > 107 THEN 1 ELSE 0 END
    WHEN variable = 'bicarbonate' THEN CASE WHEN valuenum < 22 THEN 1 ELSE 0 END
    WHEN variable = 'glucose' THEN CASE WHEN valuenum < 70 OR valuenum > 180 THEN 1 ELSE 0 END
    WHEN variable = 'lactate' THEN CASE WHEN valuenum > 2 THEN 1 ELSE 0 END
    WHEN variable = 'albumin' THEN CASE WHEN valuenum < 3.5 THEN 1 ELSE 0 END
    WHEN variable = 'total_bilirubin' THEN CASE WHEN valuenum > 1.2 THEN 1 ELSE 0 END
    WHEN variable = 'alt' THEN CASE WHEN valuenum > 40 THEN 1 ELSE 0 END
    WHEN variable = 'ast' THEN CASE WHEN valuenum > 40 THEN 1 ELSE 0 END
    WHEN variable = 'inr' THEN CASE WHEN valuenum > 1.5 THEN 1 ELSE 0 END
    WHEN variable = 'pt' THEN CASE WHEN valuenum > 14 THEN 1 ELSE 0 END
    WHEN variable = 'ptt' THEN CASE WHEN valuenum > 40 THEN 1 ELSE 0 END
    WHEN variable = 'troponin_t' THEN CASE WHEN valuenum > 0.01 THEN 1 ELSE 0 END
    ELSE NULL
  END AS abnormal_flag
FROM lab_target_72h
WHERE
  CASE
    WHEN variable = 'wbc' THEN valuenum > 0 AND valuenum < 500
    WHEN variable = 'hemoglobin' THEN valuenum > 0 AND valuenum < 25
    WHEN variable = 'hematocrit' THEN valuenum > 0 AND valuenum < 80
    WHEN variable = 'platelet' THEN valuenum > 0 AND valuenum < 3000
    WHEN variable = 'creatinine' THEN valuenum >= 0 AND valuenum < 40
    WHEN variable = 'bun' THEN valuenum >= 0 AND valuenum < 400
    WHEN variable = 'sodium' THEN valuenum > 80 AND valuenum < 200
    WHEN variable = 'potassium' THEN valuenum > 1 AND valuenum < 12
    WHEN variable = 'chloride' THEN valuenum > 50 AND valuenum < 160
    WHEN variable = 'bicarbonate' THEN valuenum > 0 AND valuenum < 80
    WHEN variable = 'glucose' THEN valuenum > 0 AND valuenum < 1500
    WHEN variable = 'lactate' THEN valuenum >= 0 AND valuenum < 50
    WHEN variable = 'albumin' THEN valuenum > 0 AND valuenum < 10
    WHEN variable = 'total_bilirubin' THEN valuenum >= 0 AND valuenum < 80
    WHEN variable = 'alt' THEN valuenum >= 0 AND valuenum < 50000
    WHEN variable = 'ast' THEN valuenum >= 0 AND valuenum < 50000
    WHEN variable = 'inr' THEN valuenum > 0 AND valuenum < 30
    WHEN variable = 'pt' THEN valuenum > 0 AND valuenum < 300
    WHEN variable = 'ptt' THEN valuenum > 0 AND valuenum < 300
    WHEN variable = 'troponin_t' THEN valuenum >= 0 AND valuenum < 10000
    ELSE valuenum IS NOT NULL
  END;
")

DBI::dbExecute(con, "
CREATE OR REPLACE TABLE vital_target_72h AS
SELECT
  c.subject_id,
  c.hadm_id,
  c.stay_id,
  CAST(c.intime AS TIMESTAMP) AS intime,
  m.domain,
  m.variable,
  m.scientific_module,
  m.itemid,
  CAST(ce.charttime AS TIMESTAMP) AS charttime,
  date_diff('minute', CAST(c.intime AS TIMESTAMP), CAST(ce.charttime AS TIMESTAMP)) / 60.0 AS hours_from_icu,
  CASE
    WHEN m.variable = 'temperature' AND m.itemid = 223761
      THEN (TRY_CAST(ce.valuenum AS DOUBLE) - 32.0) * 5.0 / 9.0
    ELSE TRY_CAST(ce.valuenum AS DOUBLE)
  END AS valuenum
FROM cohort_enhanced_r c
INNER JOIN chartevents ce
  ON c.subject_id = CAST(ce.subject_id AS BIGINT)
 AND c.hadm_id = CAST(ce.hadm_id AS BIGINT)
 AND c.stay_id = CAST(ce.stay_id AS BIGINT)
INNER JOIN vital_item_map m
  ON CAST(ce.itemid AS BIGINT) = m.itemid
WHERE
  TRY_CAST(ce.valuenum AS DOUBLE) IS NOT NULL
  AND CAST(ce.charttime AS TIMESTAMP) >= CAST(c.intime AS TIMESTAMP)
  AND CAST(ce.charttime AS TIMESTAMP) < CAST(c.intime AS TIMESTAMP) + INTERVAL '72 hours';
")

DBI::dbExecute(con, "
CREATE OR REPLACE TABLE vital_target_72h_clean AS
SELECT
  *,
  CASE
    WHEN variable = 'heart_rate' THEN CASE WHEN valuenum > 100 OR valuenum < 50 THEN 1 ELSE 0 END
    WHEN variable = 'sbp' THEN CASE WHEN valuenum < 90 THEN 1 ELSE 0 END
    WHEN variable = 'dbp' THEN CASE WHEN valuenum < 60 THEN 1 ELSE 0 END
    WHEN variable = 'map' THEN CASE WHEN valuenum < 65 THEN 1 ELSE 0 END
    WHEN variable = 'resp_rate' THEN CASE WHEN valuenum > 24 OR valuenum < 10 THEN 1 ELSE 0 END
    WHEN variable = 'spo2' THEN CASE WHEN valuenum < 90 THEN 1 ELSE 0 END
    WHEN variable = 'temperature' THEN CASE WHEN valuenum < 36 OR valuenum > 38 THEN 1 ELSE 0 END
    WHEN variable = 'gcs_eye' THEN CASE WHEN valuenum < 4 THEN 1 ELSE 0 END
    WHEN variable = 'gcs_verbal' THEN CASE WHEN valuenum < 5 THEN 1 ELSE 0 END
    WHEN variable = 'gcs_motor' THEN CASE WHEN valuenum < 6 THEN 1 ELSE 0 END
    ELSE NULL
  END AS abnormal_flag
FROM vital_target_72h
WHERE
  CASE
    WHEN variable = 'heart_rate' THEN valuenum BETWEEN 20 AND 260
    WHEN variable = 'sbp' THEN valuenum BETWEEN 40 AND 300
    WHEN variable = 'dbp' THEN valuenum BETWEEN 10 AND 200
    WHEN variable = 'map' THEN valuenum BETWEEN 20 AND 250
    WHEN variable = 'resp_rate' THEN valuenum BETWEEN 4 AND 80
    WHEN variable = 'spo2' THEN valuenum BETWEEN 20 AND 100
    WHEN variable = 'temperature' THEN valuenum BETWEEN 25 AND 45
    WHEN variable = 'gcs_eye' THEN valuenum BETWEEN 1 AND 4
    WHEN variable = 'gcs_verbal' THEN valuenum BETWEEN 1 AND 5
    WHEN variable = 'gcs_motor' THEN valuenum BETWEEN 1 AND 6
    ELSE valuenum IS NOT NULL
  END;
")

DBI::dbExecute(con, "
CREATE OR REPLACE TABLE feature_long_72h_clean AS
SELECT
  domain, variable, scientific_module,
  subject_id, hadm_id, stay_id, intime, charttime, hours_from_icu, valuenum, abnormal_flag
FROM lab_target_72h_clean
UNION ALL
SELECT
