## =========================================================
## 10. Build feature tables by window
## =========================================================
build_feature_long <- function(con, window_hour) {
  sql <- sprintf("
    WITH dat AS (
      SELECT *
      FROM feature_long_72h_clean
      WHERE hours_from_icu >= 0
        AND hours_from_icu < %d
    ),
    ranked AS (
      SELECT
        *,
        ROW_NUMBER() OVER (
          PARTITION BY stay_id, variable
          ORDER BY hours_from_icu ASC, charttime ASC
        ) AS rn_first,
        ROW_NUMBER() OVER (
          PARTITION BY stay_id, variable
          ORDER BY hours_from_icu DESC, charttime DESC
        ) AS rn_last
      FROM dat
    )
    SELECT
      stay_id,
      domain,
      scientific_module,
      variable,
      COUNT(*) AS n_measures,
      AVG(valuenum) AS mean_value,
      MIN(valuenum) AS min_value,
      MAX(valuenum) AS max_value,
      STDDEV_SAMP(valuenum) AS sd_value,
      MAX(CASE WHEN rn_first = 1 THEN valuenum END) AS first_value,
      MAX(CASE WHEN rn_last = 1 THEN valuenum END) AS last_value,
      MAX(CASE WHEN rn_first = 1 THEN hours_from_icu END) AS first_hour,
      MAX(CASE WHEN rn_last = 1 THEN hours_from_icu END) AS last_hour,
      AVG(abnormal_flag) AS abnormal_ratio,
      SUM(abnormal_flag) AS abnormal_n,
      MAX(CASE WHEN rn_last = 1 THEN valuenum END)
        - MAX(CASE WHEN rn_first = 1 THEN valuenum END) AS delta_value,
      CASE
        WHEN MAX(CASE WHEN rn_last = 1 THEN hours_from_icu END)
             - MAX(CASE WHEN rn_first = 1 THEN hours_from_icu END) > 0
        THEN (
          MAX(CASE WHEN rn_last = 1 THEN valuenum END)
          - MAX(CASE WHEN rn_first = 1 THEN valuenum END)
        ) / (
          MAX(CASE WHEN rn_last = 1 THEN hours_from_icu END)
          - MAX(CASE WHEN rn_first = 1 THEN hours_from_icu END)
        )
        ELSE NULL
      END AS slope_per_hour
    FROM ranked
    GROUP BY stay_id, domain, scientific_module, variable
    ORDER BY stay_id, domain, scientific_module, variable;
  ", window_hour)
  DBI::dbGetQuery(con, sql)
}

