feature_long_to_wide <- function(df_long) {
  df_long %>%
    select(
      stay_id, variable,
      n_measures, mean_value, min_value, max_value, sd_value,
      first_value, last_value, abnormal_ratio, abnormal_n,
      delta_value, slope_per_hour
    ) %>%
    pivot_wider(
      id_cols = stay_id,
      names_from = variable,
      values_from = c(
        n_measures, mean_value, min_value, max_value, sd_value,
        first_value, last_value, abnormal_ratio, abnormal_n,
        delta_value, slope_per_hour
      ),
      names_glue = "{variable}_{.value}"
    )
}

