## =========================================================
## 11. Landmark datasets
## =========================================================
make_landmark_dataset <- function(cohort_df, feature_wide, landmark_hour, feature_window_label) {

  tmp <- cohort_df %>%
    mutate(
      landmark_hour = landmark_hour,
      feature_window = feature_window_label,
      landmark_time = intime + landmark_hour * 3600,
      alive_at_landmark = ifelse(is.na(death_time_any) | death_time_any >= landmark_time, 1, 0),
      in_icu_at_landmark = ifelse(outtime >= landmark_time, 1, 0),
      death_30d_after_landmark = ifelse(
        !is.na(death_time_any) &
          death_time_any >= landmark_time &
          death_time_any <= intime + 30 * 24 * 3600,
        1, 0
      ),
      days_from_landmark_to_death = ifelse(
        death_30d_after_landmark == 1,
        as.numeric(difftime(death_time_any, landmark_time, units = "days")),
        NA_real_
      )
    ) %>%
    filter(alive_at_landmark == 1) %>%
    left_join(feature_wide, by = "stay_id")

  tmp
}

