feature_dictionary <- bind_rows(lab_itemid_manual, vital_itemid_manual) %>%
  distinct(domain, variable, scientific_module) %>%
  arrange(domain, scientific_module, variable)

calc_missingness_from_long <- function(df_long, total_n, window_label) {
  feature_dictionary %>%
    select(scientific_module, variable) %>%
    distinct() %>%
    left_join(
      df_long %>%
        group_by(scientific_module, variable) %>%
        summarise(
          n_with_any_measure = n_distinct(stay_id),
          n_total_records = n(),
          .groups = "drop"
        ),
      by = c("scientific_module", "variable")
    ) %>%
    mutate(
      n_with_any_measure = ifelse(is.na(n_with_any_measure), 0, n_with_any_measure),
      n_total_records = ifelse(is.na(n_total_records), 0, n_total_records),
      window = window_label,
      n_total_icu_patients = total_n,
      n_missing = total_n - n_with_any_measure,
      availability_pct = n_with_any_measure / total_n * 100,
      missing_pct = 100 - availability_pct
    ) %>%
    arrange(missing_pct, scientific_module, variable)
}

