## =========================================================
## 16. Figure 2D: refined time-course plot
## =========================================================
key_vars_timecourse <- c(
  "heart_rate", "map", "spo2", "creatinine",
  "bicarbonate", "lactate", "wbc", "troponin_t"
)

pretty_var_names2 <- c(
  heart_rate = "Heart rate",
  map = "MAP",
  spo2 = "SpO2",
  creatinine = "Creatinine",
  bicarbonate = "Bicarbonate",
  lactate = "Lactate",
  wbc = "WBC",
  troponin_t = "Troponin T"
)

DBI::dbWriteTable(
  con,
  "key_vars_timecourse_tmp",
  data.frame(variable = key_vars_timecourse),
  overwrite = TRUE
)

timecourse_bin_sql <- "
WITH dat AS (
  SELECT
    f.stay_id,
    f.variable,
    f.valuenum,
    CASE
      WHEN hours_from_icu >= 0  AND hours_from_icu < 6  THEN '0-6h'
      WHEN hours_from_icu >= 6  AND hours_from_icu < 12 THEN '6-12h'
      WHEN hours_from_icu >= 12 AND hours_from_icu < 24 THEN '12-24h'
      WHEN hours_from_icu >= 24 AND hours_from_icu < 48 THEN '24-48h'
      WHEN hours_from_icu >= 48 AND hours_from_icu < 72 THEN '48-72h'
      ELSE NULL
    END AS time_bin
  FROM feature_long_72h_clean f
  INNER JOIN key_vars_timecourse_tmp k
    ON f.variable = k.variable
  WHERE hours_from_icu >= 0
    AND hours_from_icu < 72
),
stay_bin AS (
  SELECT
    stay_id,
    variable,
    time_bin,
    AVG(valuenum) AS stay_bin_mean
  FROM dat
  WHERE time_bin IS NOT NULL
  GROUP BY stay_id, variable, time_bin
)
SELECT *
FROM stay_bin;
"

timecourse_bin_df <- DBI::dbGetQuery(con, timecourse_bin_sql)

outcome_df <- cohort %>%
  select(stay_id, mortality_30d_from_icu) %>%
  distinct() %>%
  mutate(
    outcome_group = case_when(
      mortality_30d_from_icu == 1 ~ "30-day non-survivor",
      mortality_30d_from_icu == 0 ~ "30-day survivor",
      TRUE ~ NA_character_
    )
  )

timecourse_bin_df <- timecourse_bin_df %>%
  left_join(outcome_df, by = "stay_id") %>%
  filter(!is.na(outcome_group))

timecourse_plot_df <- timecourse_bin_df %>%
  group_by(variable, time_bin, outcome_group) %>%
  summarise(
    median_value = median(stay_bin_mean, na.rm = TRUE),
    q25 = quantile(stay_bin_mean, 0.25, na.rm = TRUE),
    q75 = quantile(stay_bin_mean, 0.75, na.rm = TRUE),
    n = n(),
    .groups = "drop"
  ) %>%
  mutate(
    time_bin = factor(time_bin, levels = c("0-6h", "6-12h", "12-24h", "24-48h", "48-72h")),
    variable_pretty = factor(pretty_var_names2[variable], levels = pretty_var_names2[key_vars_timecourse]),
    outcome_group = factor(outcome_group, levels = c("30-day survivor", "30-day non-survivor"))
  )

threshold_df <- tibble::tribble(
  ~variable_pretty, ~threshold,
  "Heart rate", 100,
  "MAP", 65,
  "SpO2", 90,
  "Creatinine", 1.5,
  "Bicarbonate", 22,
  "Lactate", 2.0,
  "WBC", 12,
  "Troponin T", NA_real_
)

fig2d_new <- ggplot(
  timecourse_plot_df,
  aes(
    x = time_bin,
    y = median_value,
    group = outcome_group,
    color = outcome_group,
    fill = outcome_group
  )
) +
  geom_ribbon(aes(ymin = q25, ymax = q75), alpha = 0.25, linewidth = 0, color = NA) +
  geom_line(linewidth = 1.8) +
  geom_point(size = 3.2) +
  geom_hline(
    data = threshold_df %>% filter(!is.na(threshold)),
    aes(yintercept = threshold),
    inherit.aes = FALSE,
    linetype = "dashed",
    linewidth = 0.7,
    color = pal_red,
    alpha = 0.95
  ) +
  facet_wrap(~ variable_pretty, scales = "free_y", ncol = 4) +
  scale_color_manual(values = c(
    "30-day survivor" = pal_blue,
    "30-day non-survivor" = pal_gold
  )) +
  scale_fill_manual(values = c(
    "30-day survivor" = pal_graybg,
    "30-day non-survivor" = pal_cream
  )) +
  labs(
    title = "Figure 2D. Early trajectories of representative variables by 30-day mortality",
    subtitle = "Lines denote medians; ribbons denote interquartile ranges; red dashed lines indicate clinical thresholds",
    x = "Time after ICU admission",
    y = "Value",
    color = NULL,
    fill = NULL
  ) +
  theme_pub2(base_size = 16) +
  theme(
    legend.position = "top",
    legend.box = "horizontal",
    axis.text.x = element_text(face = "bold", angle = 30, hjust = 1),
    strip.text = element_text(face = "bold", size = 15)
  )

save_plot_dual2(fig2d_new, "Figure2D_Key_variable_timecourses_refined", width = 15, height = 9.5)

